"""CPU geometry checks for the proposed alley and adjacent striped access aisle.

The scene coordinates are construction targets, not proof of Native realization.
"""
from __future__ import annotations

import argparse
import json
import math
from pathlib import Path


def _box(raw, name):
    if not isinstance(raw, list) or len(raw) != 4:
        raise ValueError(name + " requires [xmin,ymin,xmax,ymax]")
    if any(not isinstance(v, (float, int)) or not math.isfinite(v) for v in raw):
        raise ValueError(name + " has nonfinite coordinates")
    x0, y0, x1, y1 = raw
    if x0 >= x1 or y0 >= y1:
        raise ValueError(name + " has nonpositive area")
    return x0, y0, x1, y1


def validate(scene):
    alley = _box(scene["alley_xy_m"], "alley")
    aisle = _box(scene["access_aisle_xy_m"], "access aisle")
    parking = _box(scene["designated_parking_xy_m"], "designated parking")
    route = scene["ego_route_xy_m"]
    if len(route) < 2 or any(len(point) != 2 for point in route):
        raise ValueError("ego route needs at least two XY points")
    width = scene["ego_width_m"]
    if not isinstance(width, (float, int)) or width <= 0:
        raise ValueError("invalid ego width")
    if aisle[1] != alley[3] or parking[1] != aisle[3]:
        raise ValueError("access aisle must be beside alley and designated parking")
    if not (alley[0] <= aisle[0] < aisle[2] <= alley[2] and aisle[0] <= parking[0] < parking[2] <= aisle[2]):
        raise ValueError("access aisle and parking must share the alley segment")
    stripes = scene["contrasting_stripes_xy_m"]
    if len(stripes) < 3:
        raise ValueError("access aisle requires multiple contrasting stripes")
    for stripe in stripes:
        sx0, sy0, sx1, sy1 = _box(stripe, "stripe")
        if not (aisle[0] <= sx0 < sx1 <= aisle[2] and aisle[1] <= sy0 < sy1 <= aisle[3]):
            raise ValueError("contrasting stripe lies outside access aisle")
    margin = width / 2
    for point in route:
        x, y = point
        if not (alley[0] + margin <= x <= alley[2] - margin and
                alley[1] + margin <= y <= alley[3] - margin):
            raise ValueError("ego body does not clear alley route")
    route_length = sum(math.hypot(b[0] - a[0], b[1] - a[1])
                       for a, b in zip(route, route[1:]))
    if route_length < 90:
        raise ValueError("proposed route is shorter than 45 seconds at nominal 2 m/s")
    if scene["surface_role"] != "access_aisle_adjacent_to_designated_handicapped_parking":
        raise ValueError("ordinary travel lane is not the access aisle")
    return {"route_clearance_verified_offline": True, "route_length_m": route_length,
            "stripe_count": len(stripes),
            "access_aisle_adjacent_to_parking": True, "native_realization_confirmed": False}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--scene", type=Path, required=True)
    args = parser.parse_args()
    print(json.dumps(validate(json.loads(args.scene.read_text())), sort_keys=True))


if __name__ == "__main__":
    main()

"""Validate original sources before authoring an interior-attention sweep.

This checks provenance and physical sweep feasibility. It does not decide the
legal meaning of full time and attention or expand a sweep on its own.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import math
from pathlib import Path


ASSIGNMENT = "testing__C10301__LVMC-11-22-010__motor_vehicle_driver"
LAW = "LVMC-11-22-010"
REQUIRED_SOURCES = ("municipal_jurisdiction", "original_site", "interior_sensor", "control_feasibility")


def _finite(value: object, name: str) -> float:
    if type(value) not in (int, float) or not math.isfinite(value):
        raise ValueError(name + " must be a finite number")
    return float(value)


def _source(packet: dict, key: str, root: Path) -> dict:
    entry = packet.get("sources", {}).get(key)
    if not isinstance(entry, dict) or entry.get("review_status") != "reviewed":
        raise ValueError("reviewed source required: " + key)
    path = Path(entry.get("path", ""))
    if not path.is_absolute():
        path = root / path
    if not path.is_file() or path.is_symlink():
        raise ValueError("source file missing or symlinked: " + key)
    actual = hashlib.sha256(path.read_bytes()).hexdigest()
    if actual != entry.get("sha256"):
        raise ValueError("source hash mismatch: " + key)
    if not isinstance(entry.get("citation"), str) or not entry["citation"].strip():
        raise ValueError("source citation required: " + key)
    return {"path": str(path.resolve()), "sha256": actual, "citation": entry["citation"]}


def validate(packet_path: Path, *, allow_diagnostic: bool = False) -> dict:
    packet_path = Path(packet_path)
    if not packet_path.is_file() or packet_path.is_symlink():
        raise ValueError("reviewed attention packet missing or symlinked")
    raw = packet_path.read_bytes()
    packet = json.loads(raw)
    if packet.get("format") != "worker-reviewed-attention-sweep" or packet.get("assignment_id") != ASSIGNMENT or packet.get("law_id") != LAW:
        raise ValueError("attention packet identity mismatch")
    if packet.get("diagnostic_fixture") is not False and not allow_diagnostic:
        raise ValueError("diagnostic attention packet cannot authorize a sweep")
    sources = {key: _source(packet, key, packet_path.parent) for key in REQUIRED_SOURCES}
    axis = packet.get("axis", {})
    if axis.get("variable") != "interior_distraction_target_s" or axis.get("observable") != "original_eyes_off_road_duration_s" or axis.get("unit") != "s":
        raise ValueError("source-bound interior attention axis required")
    minimum = _finite(axis.get("min"), "axis minimum")
    maximum = _finite(axis.get("max"), "axis maximum")
    spacing = _finite(axis.get("spacing"), "axis spacing")
    if minimum < 0 or maximum > 45 or maximum <= minimum or spacing <= 0 or maximum - minimum < 2 * spacing:
        raise ValueError("physical axis needs at least three feasible levels")
    if abs(round((maximum - minimum) / spacing) * spacing - (maximum - minimum)) > 1e-6:
        raise ValueError("physical axis endpoints must align with spacing")
    feasibility = json.loads(Path(sources["control_feasibility"]["path"]).read_text())
    if feasibility.get("format") != "reviewed-attention-control-feasibility" or feasibility.get("native_verified") is not True:
        raise ValueError("original control feasibility readback required")
    if any(_finite(feasibility.get(k), "feasibility " + k) != v for k, v in
           (("minimum_s", minimum), ("maximum_s", maximum), ("resolution_s", spacing))):
        raise ValueError("axis differs from reviewed physical feasibility")
    sensor = json.loads(Path(sources["interior_sensor"]["path"]).read_text())
    if sensor.get("format") != "reviewed-original-interior-sensor" or sensor.get("native_verified") is not True:
        raise ValueError("original interior sensor readback required")
    if sensor.get("observable") != axis["observable"] or not sensor.get("sensor_id"):
        raise ValueError("interior sensor cannot measure selected observable")
    if sensor.get("frame_join") != "original_native_frame" or sensor.get("sampling_rate_hz") != 20:
        raise ValueError("20 Hz original-frame interior join required")
    measurement = axis.get("measurement", {})
    if measurement.get("method") != "original interior sensor cumulative duration history" or measurement.get("statistic") != "max" or measurement.get("time_window") != "full original 45-second alley operation":
        raise ValueError("interior measurement contract missing")
    if not axis.get("range_rationale") or not axis.get("spacing_rationale"):
        raise ValueError("physical range and spacing rationale required")
    return {"format": "worker-reviewed-attention-intake", "assignment_id": ASSIGNMENT,
            "packet_sha256": hashlib.sha256(raw).hexdigest(), "source_sha256": {k: v["sha256"] for k, v in sources.items()},
            "axis": axis, "sensor_id": sensor["sensor_id"],
            "legal_judgment": "unresolved", "diagnostic_fixture": packet.get("diagnostic_fixture") is not False}


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--packet", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    if args.output.exists() or args.output.is_symlink():
        raise ValueError("attention intake output already exists")
    result = validate(args.packet)
    args.output.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n")


if __name__ == "__main__":
    main()

"""Check exact alley measurement contracts against sealed saved sources."""
from __future__ import annotations

import hashlib
import json
from pathlib import Path


SOURCE_FILES = {
    "ego": "ego.jsonl",
    "context": "context.jsonl",
    "operation": "operation.jsonl",
    "camera_frame_map": "camera-frame-map.jsonl",
}


def check(contract_path: Path, attempt: Path, measurement: dict) -> dict:
    contract = json.loads(contract_path.read_text(encoding="utf-8"))
    if contract.get("format") != "worker-measurement-contract":
        raise ValueError("unknown measurement contract")
    case_id = contract.get("case_id")
    if not case_id or measurement.get("case_id") != case_id:
        raise ValueError("exact measurement case mismatch")
    if measurement.get("selected_requirement") != "LVMC-11-22-010":
        raise ValueError("selected statutory requirement mismatch")
    interior = measurement.get("interior_source_audit")
    expected_state = "unresolved" if interior is not None else "unobserved"
    if measurement.get("attention_state") != expected_state or measurement.get("legal_judgment") != "unresolved":
        raise ValueError("unsupported interior attention or legal judgment")
    if interior is not None:
        if (interior.get("case_id") != case_id or interior.get("original_frames") != 900
                or interior.get("legal_judgment") != "unresolved"
                or interior.get("physical_acceptance_claimed") is not False):
            raise ValueError("original interior measurement contract differs")
    if measurement.get("original_frames") != 900 or measurement.get("decoded_original_pngs") != 3600:
        raise ValueError("incomplete original capture window")
    hashes = measurement.get("source_sha256", {})
    for key, name in SOURCE_FILES.items():
        source = attempt / name
        if not source.is_file():
            raise ValueError("Missing required source: " + name)
        if hashlib.sha256(source.read_bytes()).hexdigest() != hashes.get(key):
            raise ValueError("original source hash mismatch: " + name)
    operation = measurement.get("operation_measurement", {})
    if operation.get("frame_count") != 900 or operation.get("case_id") != case_id:
        raise ValueError("operation measurement identity or duration mismatch")
    expected_outputs = {row["output_key"] for row in contract.get("requirements", [])}
    if expected_outputs != {"operation_measurement", "source_sha256", "decoded_original_pngs", "attention_state"}:
        raise ValueError("selected requirement outputs incomplete")
    return {"format": "worker-alley-measurement-contract-check", "case_id": case_id,
            "source_sha256": hashes, "passed": True, "legal_judgment": "unresolved"}
